[5892] = { en = "Irondeep Supplies", tier = 4,
  t = "Voorraden uit Irondeep",
  d = "Voordat de gevechten begonnen, hebben we voorraden voor Dun Baldar in de Irondeep-mijn opgeslagen. De troggs die daar naar boven kwamen, waren niet zo'n probleem toen we nog extra troepen hadden om de mijn te bewaken. Maar nu we tegen de Horde vechten, kunnen we Irondeep niet onder controle houden.$B$BWe hebben de voorraden in Irondeep nodig, $N. Ga de mijn in en breng me er een lading van.",
  o = "Breng 10 Irondeep Supplies naar de Alliance Quartermaster in Dun Baldar.",
  p = "Heb je de voorraden, $N? We kunnen er nooit genoeg hebben!",
  c = "Goed gedaan! Ik zal deze voorraden goed gebruiken! Bedankt, $N!",
  g = { {"voorraden", "supplies (voorraad)"}, {"gevechten", "fighting, battles (gevecht)"}, {"opgeslagen", "stored (opslaan)"}, {"mijn", "mine"}, {"troepen", "troops (troep)"}, {"bewaken", "to guard"}, {"onder controle houden", "to maintain control"}, {"lading", "load"} },
