[6982] = { en = "Coldtooth Supplies", tier = 4,
  t = "Voorraden uit Coldtooth",
  d = "De Coldtooth-mijn is een opslagplaats van de Horde. Ik kan het eten dat ze hun troepen geven niet verdragen, en hun wapens en wapenrusting zijn in een vreselijke staat! Maar... in tijden als deze, nu voorraden zo belangrijk zijn, kunnen we gebruiken wat zij hebben.$B$BGa de Coldtooth-mijn in en breng hun voorraden mee terug. Dat helpt de Alliance om strijdklaar te blijven, en het neemt uitrusting die hard nodig is weg bij de krijgers van de Horde.$B$BSucces, $N. De mijn ligt ver in het zuiden, diep in het gebied van de Horde.",
  o = "Breng 10 Coldtooth Supplies naar de Alliance Quartermaster in Dun Baldar.",
  p = "Ben je in de Coldtooth-mijn geweest, $N? Heb je de voorraden waar ik om vroeg?",
  c = "Ah, je hebt ze. Goed werk, $N! Deze voorraden ruiken een beetje muf, omdat ze zo lang in die donkere mijn hebben gelegen, maar we gebruiken ze toch.$B$BBedankt, $N. Wat je doet, is van levensbelang om onze strijdkrachten op peil te houden.",
  g = { {"opslagplaats", "storage depot"}, {"verdragen", "to stomach, to bear"}, {"wapenrusting", "armour"}, {"vreselijke", "atrocious, terrible (vreselijk)"}, {"strijdklaar", "ready for battle, in fighting shape"}, {"uitrusting", "equipment"}, {"gebied", "territory, area"}, {"muf", "musty"}, {"van levensbelang", "vital"}, {"strijdkrachten", "fighting forces"}, {"op peil te houden", "to keep up to standard, to maintain"} },
},

[6781] = { en = "More Armor Scraps", tier = 4,
  t = "Meer pantserresten",
  p = "$N, we hebben meer pantserresten nodig om onze troepen te bevoorraden!",
  c = "Dit zijn goede stukken, $N. Ik kan ze gebruiken om nieuwe uitrusting voor onze troepen te maken.$B$BAls mijn voorraad hoog genoeg wordt, gaan onze ervaren gevechtseenheden misschien het veld op!",
  g = { {"pantserresten", "armour scraps (pantserrest)"}, {"bevoorraden", "to supply"}, {"uitrusting", "equipment"}, {"voorraad", "supply, stock"}, {"ervaren", "experienced, seasoned"}, {"gevechtseenheden", "fighting units (gevechtseenheid)"}, {"het veld op", "onto the (battle)field"} },
