[6846] = { en = "Begin the Attack!", tier = 4,
  t = "Begin de aanval!",
  p = "Mijn troepen zijn bevoorraad en klaar om aan te vallen. We hebben alleen nog bevelen van Noreg Stormpike nodig, en dan stuur ik ze de strijd in!",
  c = "Ah, de bevelen! Er staat dat ik mag aanvallen wanneer ik wil, en wat ik wil is... nu!",
