},

[6848] = { en = "Master Ryson's All Seeing Eye", tier = 4,
  t = "Het Alziende Oog van Master Ryson",
  d = "Jouw oorlog in het hart van Alterac betekent niets voor het Syndicate, $c. Wij doen wat we altijd hebben gedaan: wachten tot er een duidelijke winnaar opstaat uit de as en het puin van deze waanzin, en dan toeslaan.$B$BDaarom zijn we hier nu echter niet. Het All Seeing Eye is verloren gegaan: de Winterax-trollen van deze streek hebben het meegenomen.$B$BHaal het Eye terug, en onze diensten zijn van jou, voor de tijd die jouw kant nog rest.$B$BKom terug naar mij zodra je het oog hebt, zodat ik je kan onderzoeken.$B$B<Master Ryson grijnst.>",
  o = "Haal Master Ryson's All Seeing Eye terug uit de Winterax-grotten en breng het terug naar Master Ryson.$B$BWees gewaarschuwd: men zegt dat er op Master Ryson's All Seeing Eye een vreselijke vloek rust!",
  e = "Master Ryson's All Seeing Eye teruggevonden",
  g = { {"alziende", "all-seeing"}, {"winnaar", "victor, winner"}, {"as", "ashes"}, {"puin", "rubble"}, {"waanzin", "madness"}, {"toeslaan", "to strike"}, {"echter", "however"}, {"verloren gegaan", "been lost (verloren gaan)"}, {"streek", "region"}, {"diensten", "services (dienst)"}, {"rest", "remains (resten)"}, {"onderzoeken", "to examine"}, {"grijnst", "grins (grijnzen)"}, {"gewaarschuwd", "warned (waarschuwen)"}, {"vloek", "curse"} },
},

[6862] = { en = "Zinfizzlex's Portable Shredder Unit", tier = 4,
  t = "De draagbare shredder van Zinfizzlex",
  p = "Ik wil net zo graag als jij mijn draagbare shredder uitproberen, $r, maar voordat ik de bouwset kan maken, heb ik materialen nodig - heel veel materialen! $b$bOm precies te zijn: ik heb een berg thorium, mithril en ijzer nodig. Ook heb ik per apparaat één stoomzaag nodig. Die moet je bij de houtzagerij halen. $b$bToen ik hier rondsnuffelde (voordat ik gevangen werd), zag ik een stapel stoomzagen in het houthakkerskamp van de Stormpike. $b$bMaster Engineer Zinfizzlex wil dat je hem het volgende brengt:",
  g = { {"draagbare", "portable (draagbaar)"}, {"uitproberen", "to try out"}, {"bouwset", "kit"}, {"om precies te zijn", "to be exact"}, {"ijzer", "iron"}, {"apparaat", "unit, device"}, {"stoomzaag", "steamsaw"}, {"houtzagerij", "lumber mill, sawmill"}, {"rondsnuffelde", "nosed around (rondsnuffelen)"}, {"stapel", "pile, stack"}, {"houthakkerskamp", "lumber camp"} },
},

[6881] = { en = "Ivus the Forest Lord", tier = 4,
  t = "Ivus, Heer van het Woud",
  p = "De Frostwolf Clan wordt beschermd door een smet van elementaire energie. Hun sjamanen bemoeien zich met krachten die ons zeker allemaal zullen vernietigen als niemand hen tegenhoudt.$b$bDe schade is te groot geworden om door de Circle beheerst te worden! Ivus moet worden opgeroepen om ons te helpen.$b$bDe soldaten van de Frostwolf dragen elementaire amuletten die Storm Crystals heten. We kunnen die amuletten gebruiken om Ivus op te roepen. Trek erop uit en neem de kristallen, $n!",
  c = "Goed gedaan, $N. Ik zal de kracht van dit amulet gebruiken om de magie te versterken die al verzameld is. Wanneer er genoeg kracht is verzameld, zal ik de verzamelde energie bundelen en de Heer van het Woud oproepen om onze zaak te steunen.",
  g = { {"smet", "taint, stain"}, {"elementaire", "elemental (elementair)"}, {"sjamanen", "shamans (sjamaan)"}, {"bemoeien zich met", "meddle in (zich bemoeien met)"}, {"tegenhoudt", "stops, holds back (tegenhouden)"}, {"beheerst", "controlled (beheersen)"}, {"opgeroepen", "called, summoned (oproepen)"}, {"amuletten", "charms, amulets (amulet)"}, {"trek erop uit", "venture forth (erop uittrekken)"}, {"versterken", "to augment, to strengthen"}, {"bundelen", "to focus, to bundle"}, {"zaak", "cause"}, {"steunen", "to support"} },
},

[6941] = { en = "Call of Air - Vipore's Fleet", tier = 4,
  t = "Roep van de lucht - de vloot van Vipore",
  p = "De elite-eenheden van de Frostwolf die de linies bewaken, moeten worden aangepakt, soldaat! Ik geef jou de taak om die kudde wilden uit te dunnen. Kom terug met medailles van hun luitenants en legionairs. Als ik vind dat er genoeg van dat tuig is afgehandeld, zet ik de luchtaanval in.",
  c = "Het eskader is binnenkort klaar. Ga door met je inspanningen!",
  g = { {"vloot", "fleet"}, {"eenheden", "units (eenheid)"}, {"linies", "(battle) lines (linie)"}, {"aangepakt", "dealt with (aanpakken)"}, {"kudde", "herd"}, {"wilden", "savages (wilde)"}, {"uit te dunnen", "to thin out (uitdunnen)"}, {"medailles", "medals (medaille)"}, {"legionairs", "legionnaires (legionair)"}, {"tuig", "riff-raff, rabble"}, {"afgehandeld", "dealt with (afhandelen)"}, {"luchtaanval", "air strike"}, {"eskader", "squadron, flight"}, {"inspanningen", "efforts (inspanning)"} },
},

[6942] = { en = "Call of Air - Slidore's Fleet", tier = 4,
  t = "Roep van de lucht - de vloot van Slidore",
  p = "Mijn griffioenen staan klaar om de frontlinies aan te vallen, maar ze kunnen pas aanvallen als de linies zijn uitgedund.$b$bDe Frostwolf-krijgers die de frontlinies moeten vasthouden, dragen trots medailles voor hun dienst op hun borst. Ruk die medailles van hun rottende lijken en breng ze hier.$b$bZodra de frontlinie genoeg is uitgedund, geef ik het bevel om de lucht in te gaan! Dood van boven!",
  c = "Blijf ze brengen, soldaat! De griffioenen van de Aerie zijn in een mum van tijd klaar om aan te vallen!",
  g = { {"griffioenen", "gryphons (griffioen)"}, {"frontlinies", "front lines (frontlinie)"}, {"uitgedund", "thinned out (uitdunnen)"}, {"vasthouden", "to hold"}, {"trots", "proudly, proud"}, {"borst", "chest"}, {"ruk", "rip, tear (rukken)"}, {"rottende", "rotting (rotten)"}, {"lijken", "corpses (lijk)"}, {"bevel", "order, command"}, {"in een mum van tijd", "in no time at all"} },
},

[6943] = { en = "Call of Air - Ichman's Fleet", tier = 4,
  t = "Roep van de lucht - de vloot van Ichman",
  p = "Ze hebben weinig moed meer, soldaat. Na onze laatste mislukte luchtaanval op de Horde weigeren ze te vliegen! Het is aan jou om hun moreel op te krikken.$b$bGa terug naar het slagveld en sla toe in het hart van het commando van de Frostwolf. Schakel hun commandanten en bewakers uit. Kom bij me terug met zoveel van hun medailles als je in je rugzak kunt proppen! Ik beloof je: wanneer mijn griffioenen de buit zien en het bloed van onze vijanden ruiken, zullen ze weer vliegen! Ga nu!",
  c = "Zie je het? Kijk naar hen, soldaat! Ze draaien bij... Binnenkort zal het eskader van Ichman weer toeslaan in het hart van de vallei! Stormpike zal de lucht beheersen!",
  g = { {"moed", "courage, spirit"}, {"mislukte", "failed (mislukken)"}, {"weigeren", "refuse"}, {"moreel", "morale"}, {"op te krikken", "to boost, to bolster (opkrikken)"}, {"slagveld", "battlefield"}, {"schakel uit", "take down (uitschakelen)"}, {"bewakers", "guardians, guards (bewaker)"}, {"proppen", "to stuff, to cram"}, {"buit", "loot, bounty"}, {"draaien bij", "are coming around (bijdraaien)"}, {"eskader", "squadron, flight"}, {"beheersen", "to rule, to control"} },
},

[7026] = { en = "Ram Riding Harnesses", tier = 4,
  t = "Tuigen voor de ramruiters",
  o = "null",
  p = "De Stormpike Brigade kan niet zonder zadel de strijd in stormen! We hebben tuigen nodig voor onze rijdieren; we zijn tenslotte geen wilden.$B$BWe zouden makkelijk de rammen kunnen doden die bij onze basis rondlopen om het leer te krijgen dat nodig is voor een tuig, maar dat zou idioot zijn. We hebben die rammen nodig als rijdieren.$B$BJe moet de basis van onze vijand aanvallen, de wolven doden die de Frostwolf als rijdier gebruikt en hun huiden nemen. Breng hun huiden naar mij, zodat er tuigen voor de cavalerie gemaakt kunnen worden. Ga!",
  c = "Goed gedaan, soldaat. Ik laat het je weten wanneer ik genoeg huiden heb verzameld.$B$BGa door!",
  g = { {"tuigen", "harnesses (tuig)"}, {"ramruiters", "ram riders (ramruiter)"}, {"zonder zadel", "bareback"}, {"stormen", "to charge, to storm"}, {"rijdieren", "mounts (rijdier)"}, {"tenslotte", "after all"}, {"rammen", "rams (ram)"}, {"leer", "leather"}, {"huiden", "hides (huid)"}, {"cavalerie", "cavalry"}, {"verzameld", "stockpiled, collected (verzamelen)"} },
},

[7027] = { en = "Empty Stables", tier = 4,
  t = "Lege stallen",
  d = "Kijk toch eens naar de stallen, $N! Leeg! De Stormpike Brigade heeft geen rammen om op te rijden; de cavalerie bestaat niet meer.$B$BJe moet ons helpen, soldaat. Neem deze trainingshalsband en trek de wildernis van deze vallei in. Zoek de Alterac-rammen die overal in het gebied rondlopen en vang er een met de halsband. Wanneer je een ram hebt gevangen, breng hem dan naar mij, dan zet ik hem in onze stal.$B$BAls we genoeg rammen hebben, krijgt de commandant van de ramruiters bericht. Met jouw hulp zal de cavalerie herboren worden!",
  o = "Zoek een Alterac Ram in Alterac Valley. Gebruik de Stormpike Training Collar wanneer je bij de Alterac Ram bent om het beest te 'temmen'. Als hij getemd is, volgt de Alterac Ram je terug naar de Stable Master. Spreek met de Stable Master om de vangst te laten meetellen.$b",
  p = "Zonder jouw hulp zouden de Stormpike Ram Riders geen rijdieren hebben om mee de strijd in te gaan. Je bewijst ons een grote dienst!",
  c = "De stallen zijn in een mum van tijd vol. Ga zo door!",
  e = "Ram gevangen en teruggebracht",
  g = { {"stallen", "stables (stal)"}, {"cavalerie", "cavalry"}, {"trainingshalsband", "training collar"}, {"wildernis", "wilds, wilderness"}, {"vang", "catch, snare (vangen)"}, {"bericht", "notice, message"}, {"herboren", "reborn"}, {"temmen", "to tame"}, {"getemd", "tamed (temmen)"}, {"vangst", "capture, catch"}, {"meetellen", "to count"}, {"je bewijst ons een grote dienst", "you do us a great service"}, {"in een mum van tijd", "in no time at all"} },
},

[7081] = { en = "Alterac Valley Graveyards", tier = 4,
  t = "De begraafplaatsen van Alterac Valley",
  d = "De begraafplaatsen in Alterac Valley zijn zeer gewilde gebieden. Zowel de Horde als de Alliance vecht woest om deze heilige grond. Ben jij er klaar voor om aan dat gevecht mee te doen, $N?$B$BIk wil dat je een begraafplaats van de vijand aanvalt. Zoek een begraafplaats met een banier van de Horde in het midden en trek die uit de grond! Doe dat, en je taak is voltooid....$B$BMaar als je de begraafplaats ook een paar minuten kunt vasthouden, dan komen onze troepen je snel aflossen.",
  o = "Val een begraafplaats aan en keer dan terug naar Sergeant Durgen Stormpike in de Alterac Mountains.",
  p = "$N, je hebt nog geen begraafplaats aangevallen. Kom terug als deze taak voltooid is!",
  c = "Goed gedaan! Begraafplaatsen zijn van levensbelang voor onze controle over Alterac Valley. Als je er een verovert, help je de heerschappij van de Alliance hier te verzekeren.$B$BGa nu, $N. Ga terug de strijd in, en als je een begraafplaats ziet die in handen van de Horde is... je weet wat je moet doen!",
  o1 = "Begraafplaats aangevallen",
  g = { {"begraafplaatsen", "graveyards (begraafplaats)"}, {"gewilde", "prized, sought-after (gewild)"}, {"woest", "savagely, fiercely"}, {"heilige", "sacred (heilig)"}, {"banier", "banner"}, {"vasthouden", "to hold"}, {"aflossen", "to relieve"}, {"van levensbelang", "vital"}, {"verovert", "capture, conquer (veroveren)"}, {"heerschappij", "sovereignty, rule"}, {"verzekeren", "to ensure, to secure"}, {"in handen van", "under the control of"} },
},

[7102] = { en = "Towers and Bunkers", tier = 4,
  t = "Torens en bunkers",
  d = "Torens en bunkers zijn belangrijke verdedigingsposities, dus we moeten er zoveel mogelijk vasthouden! Ik wil dat je een toren of een bunker in Alterac Valley aanvalt.$B$BGa daarvoor een toren binnen met een banier van de Horde erbovenop. Binnen zie je nog een vijandelijke banier. Trek die banier eruit, en er verschijnt een witte banier van de Alliance op zijn plaats. Goed gedaan!$B$BDan is je opdracht voor mij voltooid. Maar als je het gebied lang genoeg vasthoudt en de Horde het niet terugneemt, wordt het vernietigd!",
  o = "Vernietig de banier bij een toren of bunker van de vijand en keer dan terug naar Sergeant Durgen Stormpike in de Alterac Mountains.",
  p = "Je hebt nog geen toren aangevallen, $N! Waar wacht je nog op?",
  c = "Ik heb een rapport van het front gekregen waarin staat dat je hebt geholpen een vijandelijke banier te veroveren. Goed gedaan, $N! Nu hun troepen voor afstandsgevechten niet op hun plek staan, kunnen we de frontlinie naar voren schuiven!",
  o1 = "Banier vernietigd",
  g = { {"verdedigingsposities", "defensive positions (verdedigingspositie)"}, {"vasthouden", "to hold"}, {"erbovenop", "on top of it"}, {"vijandelijke", "enemy (vijandelijk)"}, {"verschijnt", "appears (verschijnen)"}, {"opdracht", "mission, task"}, {"vernietigd", "destroyed (vernietigen)"}, {"rapport", "report"}, {"veroveren", "to capture, to secure"}, {"afstandsgevechten", "ranged combat (afstandsgevecht)"}, {"frontlinie", "front line"}, {"schuiven", "to move, to push"} },
},

[7121] = { en = "The Quartermaster", tier = 4,
  t = "De kwartiermeester",
  d = "$N, onze kwartiermeester heeft me opgedragen om nieuwe rekruten naar hem toe te sturen. Hij heeft voorraden nodig uit de opslagplaatsen in de mijnen van Alterac, en hij stuurt je er waarschijnlijk op uit om ze te halen.$B$BVolg de weg. Je vindt onze kwartiermeester in het westen.",
  o = "Spreek met de Stormpike Quartermaster.",
  c = "Het is goed om hier verse troepen te zien, $N, maar met een beetje geluk kom je snel in actie en ben je niet lang meer vers!$B$BSpreek me nog eens aan. Ik heb taken die ik met je moet bespreken....",
  g = { {"kwartiermeester", "quartermaster"}, {"opgedragen", "charged, ordered (opdragen)"}, {"rekruten", "recruits (rekruut)"}, {"voorraden", "supplies (voorraad)"}, {"opslagplaatsen", "caches, stores (opslagplaats)"}, {"mijnen", "mines (mijn)"}, {"waarschijnlijk", "probably"}, {"stuurt je er op uit", "sends you out (eropuit sturen)"}, {"verse", "fresh (vers)"}, {"bespreken", "to discuss"} },
},

[7122] = { en = "Capture a Mine", tier = 4,
  t = "Verover een mijn",
  d = "De mijnen in Alterac Valley bevatten meer dan alleen mineralen. Zowel de Frostwolf als de Stormpike hebben extra voorraden verborgen in de Irondeep- en Coldtooth-mijnen... dat is geen slecht idee, als we ze maar onder controle konden houden!$B$BVerover een mijn en keer dan terug naar mij. Om een mijn te veroveren, ga je een mijn binnen die niet van ons is en dood je de leider. Als je dat doet, is de mijn van ons, en sturen we troepen om hem te beschermen!",
  o = "Verover een mijn die de Stormpike niet in handen heeft en keer dan terug naar Sergeant Durgen Stormpike in de Alterac Mountains.",
  p = "Je hebt de mijn nog niet veroverd, $N!$B$BAls we een mijn in handen hebben, is het veel makkelijker om er mineralen en voorraden uit te halen.",
  c = "Het is je gelukt! Goed gedaan, $N!$B$BAls we een mijn in handen hebben en er troepen gelegerd zijn, is het veel makkelijker om er mineralen en voorraden uit te halen.",
  o1 = "Mijn veroverd",
  g = { {"verover", "capture (veroveren)"}, {"bevatten", "hold, contain"}, {"mineralen", "minerals (mineraal)"}, {"verborgen", "cached, hidden (verbergen)"}, {"onder controle houden", "to maintain control"}, {"beschermen", "to protect"}, {"in handen heeft", "controls (in handen hebben)"}, {"veroverd", "captured (veroveren)"}, {"gelegerd", "stationed (legeren)"} },
},

[7141] = { en = "The Battle of Alterac", tier = 4,
  t = "De strijd om Alterac",
  d = "De Explorers' League denkt dat er artefacten in Alterac Valley liggen, maar de orcs van de Frostwolf laten ons niet op onderzoek gaan. We mogen niet toestaan dat de Horde ons wetenschappelijke werk tegenhoudt! Versla de generaal van de Frostwolf, Drek'Thar. Als hij dood is, raken de orcs hun voordeel kwijt.$B$BDrek'Thar zit in Frostwolf Keep, in het zuiden van Alterac Valley. Versla hem en keer dan terug naar mij.",
  o = "Ga Alterac Valley binnen, versla Drek'thar, de generaal van de Horde, en keer dan terug naar Prospector Stonehewer in de Alterac Mountains.",
  p = "Ga, $N. Ga naar Alterac Valley en versla de generaal van de orcs!",
  c = "Goed gedaan, $N! Nu de Horde na de dood van hun generaal een bloedneus heeft opgelopen, hebben we de ademruimte die we nodig hebben om op onderzoek te gaan!",
  e = "Versla Drek'thar.",
  g = { {"artefacten", "artifacts (artefact)"}, {"op onderzoek gaan", "to explore, to investigate"}, {"toestaan", "to allow"}, {"wetenschappelijke", "scholarly, scientific (wetenschappelijk)"}, {"tegenhoudt", "stops (tegenhouden)"}, {"versla", "defeat (verslaan)"}, {"generaal", "general"}, {"voordeel kwijt", "lose their edge (voordeel kwijtraken)"}, {"bloedneus", "bloody nose"}, {"opgelopen", "suffered, got (oplopen)"}, {"ademruimte", "breathing room"} },
},

[7162] = { en = "Proving Grounds", tier = 4,
  t = "Proefterrein",
  d = "Je bent net op tijd, $c. Deze wilden van de Frostwolf geven het gewoon niet op! We moeten hun de macht van de Stormpike laten zien. Ze moeten buigen voor onze superioriteit.$B$BVoordat je naar het slagveld gaat, wil je je vast bij de rangen van de Stormpike aansluiten.$B$BTen zuidwesten van Dun Baldar vind je de Icewing Caverns. Diep in de grotten staat een Stormpike Banner. Trek erop uit en haal die banier terug. Breng hem naar mij, en dan heb je het insigne van een Stormpike-rekruut verdiend.",
  o = "Reis naar de Icewing Caverns ten zuidwesten van Dun Baldar in Alterac Valley en haal de Stormpike Banner terug. Breng de Stormpike Banner naar Lieutenant Haggerdin in de Alterac Mountains.",
  p = "Pas op voor de harpijen in deze streek, $c. Ze denken er niet twee keer over na om je keel open te rijten!",
  c = "Neem dit insigne en draag het met trots, $N. Naarmate je rang bij de Stormpike stijgt, groeit ook het insigne. Kom bij me terug wanneer je meer eer bij de Stormpike verdient, en dan vervang ik je insigne door andere, krachtigere insignes.$B$BMisschien word je ooit een legende op dit slagveld. Als die dag ooit komt, krijg je het Eye of Command.",
  g = { {"proefterrein", "proving grounds"}, {"wilden", "savages (wilde)"}, {"buigen", "to bow"}, {"superioriteit", "superiority"}, {"slagveld", "battlefield"}, {"rangen", "ranks (rang)"}, {"aansluiten", "to join"}, {"trek erop uit", "venture forth (erop uittrekken)"}, {"insigne", "insignia, badge"}, {"rekruut", "recruit, initiate"}, {"harpijen", "harpies (harpij)"}, {"open te rijten", "to rip open (openrijten)"}, {"naarmate", "as, in proportion as"}, {"vervang", "replace (vervangen)"}, {"legende", "legend"} },
},

[7168] = { en = "Rise and Be Recognized", tier = 4,
  t = "Sta op en word erkend",
  p = "De meesten leven niet lang genoeg om boven hun eigen middelmatigheid uit te stijgen. Jij hebt bewezen dat je een voorbeeldige soldaat bent, $c. De tijd is gekomen.$B$BLaat je insigne zien.",
  c = "Laat onze vijanden zien dat een soldaat met rang hen heeft neergeslagen! Vecht voor de glorie van Stormpike!$b",
