},

[7169] = { en = "Honored Amongst the Guard", tier = 4,
  t = "Geëerd binnen de wacht",
  p = "De basis gonst van het nieuws over je daden in het Field of Strife! Je hebt onze vijand zware slagen toegebracht en hun moreel gebroken! Daarom heb je een eervolle rang bij de Stormpike verdiend.$B$BLaat je insigne zien.",
  c = "De koning weet van je heldendaden aan het front, $c. Ga door met je standvastige verdediging van de Stormpike Guard!",
  g = { {"geëerd", "honoured (eren)"}, {"wacht", "guard"}, {"gonst", "buzzes (gonzen)"}, {"daden", "deeds, exploits (daad)"}, {"slagen", "blows (slag)"}, {"toegebracht", "dealt, inflicted (toebrengen)"}, {"moreel", "morale"}, {"eervolle", "honourable (eervol)"}, {"heldendaden", "heroic deeds (heldendaad)"}, {"standvastige", "steadfast, stalwart (standvastig)"}, {"verdediging", "defence"} },
},

[7495] = { en = "Victory for the Alliance", tier = 4,
  t = "Overwinning voor de Alliance",
  d = "Je hebt het onmogelijke gedaan. De broedmoeder van de Black Dragonflight ligt dood aan je voeten. Neem haar hoofd en breng het naar de Highlord.",
  o = "Breng de Head of Onyxia naar Highlord Bolvar Fordragon in Stormwind.",
  p = "Bij Uthers baard!",
  c = "Zoveel jaren werd ik gevangen gehouden door haar betoverende blik. Eindelijk zie ik dat er recht is gedaan en dat de eer van Stormwind is hersteld! Vandaag vieren we deze glorieuze overwinning!",
  g = { {"overwinning", "victory"}, {"onmogelijke", "the impossible (onmogelijk)"}, {"broedmoeder", "brood mother"}, {"baard", "beard"}, {"betoverende", "captivating, bewitching (betoveren)"}, {"blik", "gaze, look"}, {"recht is gedaan", "justice has been done"}, {"eer", "honour"}, {"hersteld", "restored (herstellen)"}, {"vieren", "to celebrate"}, {"glorieuze", "glorious (glorieus)"} },
},

[7632] = { en = "The Ancient Leaf", tier = 4,
  t = "Het oude blad",
  d = "De opperhuid van het blad gloeit felgroen. Het oppervlak is erg ruw en gerimpeld, waardoor je verschillende nerven en plooien kunt zien.$B$BAls je moest raden, zou je zeggen dat dit blad van iets ouds en machtigs komt.$B$BMisschien moet je de oorspronkelijke eigenaar van dit blad zoeken?",
  o = "Zoek de eigenaar van het Ancient Petrified Leaf. Succes, $N; het is een grote wereld.",
  p = "<Vartrus kreunt.>",
  c = "Natuurlijk herken ik mijn eigen bladeren. Kijk nou! Het is in perfecte staat.$B$BWat goed van je dat je het terugbrengt, $C.$B$BMisschien kun jij ons van dienst zijn, en wij jou.",
  g = { {"opperhuid", "epidermis, outer skin"}, {"gloeit", "glows (gloeien)"}, {"oppervlak", "surface"}, {"gerimpeld", "wrinkled, rugose"}, {"nerven", "veins of a leaf (nerf)"}, {"plooien", "folds, wrinkles (plooi)"}, {"raden", "to guess"}, {"oorspronkelijke", "original (oorspronkelijk)"}, {"eigenaar", "owner"}, {"kreunt", "groans (kreunen)"}, {"herken", "recognize (herkennen)"}, {"van dienst zijn", "to be of service"} },
},

[7633] = { en = "An Introduction", tier = 4,
  t = "Een kennismaking",
  c = "Je ijver en eerlijkheid zijn ons opgevallen, $C.$B$BWij zijn de Ancients: beschermers van dit eens zo grote woud. Onze lichamen werden 10.000 jaar geleden vernietigd, toen Archimonde en de Burning Legion naar Hyjal oprukten. Onze geesten zijn echter heel gebleven.$B$BEr zijn taken die we je kunnen geven. Als je die voltooit, zullen de geheimen van de Ancients voor je opengaan.$B$BWeet dit: als je deze taken voltooit, hoef je alleen naar deze rots terug te keren, en dan zullen we je roep beantwoorden.",
  g = { {"kennismaking", "introduction, getting acquainted"}, {"ijver", "diligence"}, {"eerlijkheid", "honesty, integrity"}, {"opgevallen", "noticed (opvallen)"}, {"beschermers", "protectors (beschermer)"}, {"woud", "forest"}, {"oprukten", "advanced, marched (oprukken)"}, {"echter", "however"}, {"heel gebleven", "remained intact"}, {"voltooit", "complete (voltooien)"}, {"geheimen", "secrets (geheim)"}, {"roep", "call"}, {"beantwoorden", "to answer"} },
},

[7635] = { en = "A Proper String", tier = 4,
  t = "Een goede boogpees",
  d = "Vartrus kan je misschien de staf geven om een boog van de Ancients te maken, maar alleen ik kan de pees betoveren die nodig is om de boog af te maken.$B$BHet is een eenvoudige taak, nietig wezen. Dood een volwassen zwarte draak en haal de pees van zijn botten. Breng die pees naar mij, en ik zal het materiaal betoveren tot een bijna onverwoestbare boogpees.",
  o = "Stoma the Ancient heeft je gevraagd hem een Mature Black Dragon Sinew te brengen. Als je deze pees vindt, breng hem dan terug naar Stoma in Felwood.",
  p = "Ik weet zeker dat het niet moeilijk voor je zal zijn om een zwarte draak te vinden en te doden, $N. Verspil mijn tijd niet met nutteloos gepraat.",
  c = "Dit was wel een heel smerige draak. De pees stinkt naar het kwaad.$B$BGeef me even de tijd om het vuil uit dit vlees te verwijderen en de juiste betoveringen aan te brengen.",
  g = { {"boogpees", "bowstring"}, {"staf", "stave, staff"}, {"pees", "sinew; bowstring"}, {"betoveren", "to enchant"}, {"nietig", "puny, insignificant"}, {"wezen", "being, creature"}, {"volwassen", "mature, adult"}, {"onverwoestbare", "indestructible (onverwoestbaar)"}, {"verspil", "waste (verspillen)"}, {"nutteloos", "useless, idle"}, {"gepraat", "chatter, talk"}, {"smerige", "foul, filthy (smerig)"}, {"het kwaad", "evil"}, {"aan te brengen", "to apply (aanbrengen)"} },
},

[8183] = { en = "The Heart of Hakkar", tier = 4,
  t = "Het hart van Hakkar",
  d = "Het Heart of Hakkar brandt van binnenuit. Hoewel de Soulflayer verslagen is, zit de kern van zijn macht nog altijd in dit vervloekte orgaan.",
  o = "Breng het Heart of Hakkar naar Molthor op Yojamba Isle.",
  p = "$N, de stank van een kwade ziel hangt om je heen. Ben je vervloekt door de Soulflayer?",
  c = "Ah, het Heart of Hakkar. Dus de Soulflayer is gedood! Onze wereld is gered!$B$B$N, je dienst aan ons kan niet genoeg geprezen worden. Je bent werkelijk een held van dit rijk!",
  g = { {"van binnenuit", "from within"}, {"hoewel", "although"}, {"verslagen", "defeated (verslaan)"}, {"kern", "kernel, core"}, {"vervloekte", "cursed (vervloekt)"}, {"orgaan", "organ"}, {"stank", "reek, stench"}, {"kwade", "evil (kwaad)"}, {"gered", "saved (redden)"}, {"geprezen", "praised (prijzen)"}, {"werkelijk", "truly, really"}, {"rijk", "realm"} },
},

