[8288] = { en = "Only One May Rise", tier = 4,
  t = "Slechts één mag opstaan",
  d = "Er is geen tijd te verliezen! Er moet een held gevonden worden! Voor de taak die ik geef, is een leger nodig. Maar slechts één uit de menigte van mogelijke kampioenen mag opstaan om de last en de verantwoordelijkheid van een bondgenoot van het Brood op zich te nemen.$B$BIn het hol van de Lord of Blackrock leeft een zeer wreed beest. Broodlord Lashlayer bewaakt de Halls of Strife en blokkeert de weg naar het binnenste heiligdom van Nefarian. Dood dit smerige gedrocht en breng zijn hoofd naar mij. Doe dit, en je kunt aan de volgende stap van je reis beginnen.",
  o = "Breng de Head of the Broodlord Lashlayer terug naar Baristolth of the Shifting Sands in Cenarion Hold in Silithus.",
  p = "Je moet de gunst van het Brood of Nozdormu verdienen.",
  c = "Zou jij de eerste kunnen zijn die in duizend jaar de gunst van de Bronze Flight verdient?",
  g = { {"slechts", "only, merely"}, {"menigte", "crowd, throng"}, {"kampioenen", "champions (kampioen)"}, {"last", "burden"}, {"verantwoordelijkheid", "responsibility"}, {"bondgenoot", "ally"}, {"op zich te nemen", "to take upon oneself (op zich nemen)"}, {"hol", "lair, den"}, {"wreed", "cruel"}, {"blokkeert", "blocks (blokkeren)"}, {"binnenste", "innermost"}, {"heiligdom", "sanctum, sanctuary"}, {"gedrocht", "monstrosity, aberration"}, {"gunst", "favour"} },
},

[8789] = { en = "Imperial Qiraji Armaments", tier = 4,
  t = "Keizerlijke Qiraji-wapens",
  d = "We hebben duizend jaar lang niet stilgezeten, $N.$B$BWe hebben gezien hoe deze beesten hun eigen soortgenoten verslinden zodra die geen nut meer hebben. We hebben geluisterd terwijl ze plannen smeedden om onze wereld te vernietigen. En we hebben gehoord van het verraad binnen hun eigen rijen.$B$BEr zijn zwakke plekken, en we weten hoe we die in ons voordeel kunnen gebruiken.$B$BZoek hun ceremoniële wapens en breng ze naar mij. Samen met het element dat ontstaat uit de instabiliteit van hun eigen God, zullen ze een kracht van afrekening worden.",
  o = "Arygos in de Temple of Ahn'Qiraj maakt Elementium Infused Armaments voor je als je hem Imperial Qiraji Armaments en 3 Elementium Ore brengt.",
  p = "Zoek wat ik gevraagd heb. Je zult meer worden dan de som van je delen, kampioen.",
  c = "Doordrenkt met Elementium zullen deze wapens met ongelooflijk gemak door de Qiraji en hun God snijden.",
  g = { {"keizerlijke", "imperial (keizerlijk)"}, {"stilgezeten", "sat still, been idle (stilzitten)"}, {"soortgenoten", "own kind (soortgenoot)"}, {"verslinden", "devour, feast on"}, {"nut", "use, utility"}, {"plannen smeedden", "plotted, schemed (plannen smeden)"}, {"verraad", "treachery, betrayal"}, {"rijen", "ranks (rij)"}, {"zwakke plekken", "weaknesses, weak spots"}, {"voordeel", "advantage"}, {"ceremoniële", "ceremonial (ceremonieel)"}, {"instabiliteit", "instability, volatility"}, {"afrekening", "reckoning"}, {"som", "sum"}, {"doordrenkt", "infused, soaked (doordrenken)"} },
},

[8790] = { en = "Imperial Qiraji Regalia", tier = 4,
  t = "Keizerlijke Qiraji-regalia",
  d = "Arygos vermoedt dat het element dat ontstaat uit de conflicten tussen de Old Gods en hun dienaren, onder de juiste omstandigheden ook zeer dodelijk voor hen is. Ik heb het over Elementium, sterveling.$B$BZoek Imperial Qiraji Regalia en het giftige element en breng ze naar mij, dan zal ik wapens van grote kracht doordrenken.$b",
  o = "Merithra of the Dream in de Temple of Ahn'Qiraj maakt Elementium Infused Armaments voor je als je haar Imperial Qiraji Regalia en 3 Elementium Ore brengt.$b",
