  g = { {"regalia", "regalia, ceremonial insignia"}, {"vermoedt", "suspects, theorizes (vermoeden)"}, {"dienaren", "servants, minions (dienaar)"}, {"omstandigheden", "conditions, circumstances (omstandigheid)"}, {"dodelijk", "deadly"}, {"sterveling", "mortal"}, {"giftige", "toxic, poisonous (giftig)"}, {"doordrenken", "to infuse, to soak"}, {"neerslaan", "to strike down"}, {"ketenen", "chains, bonds (keten)"}, {"bevrijden", "to free"}, {"aandoen", "to inflict on"} },
},

[9023] = { en = "The Perfect Poison", tier = 4,
  t = "Het perfecte gif",
  d = "Mijn broer en ik leiden de gifzaken vanuit het landhuis Ravenholdt.$B$BLord Ravenholdt heeft me opgedragen een nieuw en zeer effectief gifmengsel op te sporen dat gemaakt kan worden van de gifzakken van de bewoners van Zul'Gurub en de Ruins of Ahn'Qiraj.$B$BIn die vervloekte ruïnes wonen twee bijzonder giftige beesten die misschien hebben wat we zoeken, $c. Breng me een gifzak van de beesten Kurinnaxx en Venoxis, en we zullen je eeuwig dankbaar zijn.",
  o = "Dirk Thunderwood in Cenarion Hold wil dat je hem Venoxis's Venom Sac en Kurinnaxx's Venom Sac brengt.",
  p = "Dit is geen snelle roof waarbij je even iets grijpt, $N. Je zult vrienden moeten meenemen.",
  c = "Ravenholdt bedankt je, held! Kies maar uit!",
  g = { {"gif", "poison"}, {"landhuis", "manor"}, {"opgedragen", "tasked, ordered (opdragen)"}, {"gifmengsel", "poison compound"}, {"op te sporen", "to track down (opsporen)"}, {"gifzakken", "venom sacs (gifzak)"}, {"bewoners", "inhabitants (bewoner)"}, {"ruïnes", "ruins (ruïne)"}, {"bijzonder", "particularly, special"}, {"giftige", "venomous, poisonous (giftig)"}, {"eeuwig", "eternally"}, {"roof", "robbery, grab"}, {"grijpt", "grabs (grijpen)"} },
},

})

